import{_ as a,a as o,e as r,l as e,ar as c,O as h,t as i}from"./chunks/framework.CK3qJuPR.js";const R=JSON.parse('{"title":"React vs Vue","description":"React 对比 Vue3 API","frontmatter":{"title":"React vs Vue","description":"React 对比 Vue3 API","tags":["React"]},"headers":[],"relativePath":"frontend/react/react2vue.md","filePath":"frontend/react/react2vue.md","lastUpdated":1761045430000}'),n={name:"frontend/react/react2vue.md"},l={id:"frontmatter-title",tabindex:"-1"};function s(d,t,u,b,f,p){return r(),o("div",null,[t[1]||(t[1]=e("div",{style:{display:"none"},hidden:"true","aria-hidden":"true"},"Are you an LLM? You can read better optimized documentation at /vite-press/frontend/react/react2vue.md for this page in Markdown format",-1)),e("h1",l,[h(i(d.$frontmatter.title)+" ",1),t[0]||(t[0]=e("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":"Permalink to “{{ $frontmatter.title }}”"},"​",-1))]),t[2]||(t[2]=c('<h1 id="vue-3-composition-api-↔-react-18-hooks-api-对照文档" tabindex="-1">Vue 3 Composition API ↔ React 18 Hooks API 对照文档 <a class="header-anchor" href="#vue-3-composition-api-↔-react-18-hooks-api-对照文档" aria-label="Permalink to “Vue 3 Composition API ↔ React 18 Hooks API 对照文档”">​</a></h1><h2 id="✅-状态管理" tabindex="-1">✅ 状态管理 <a class="header-anchor" href="#✅-状态管理" aria-label="Permalink to “✅ 状态管理”">​</a></h2><table tabindex="0"><thead><tr><th>Vue 3</th><th>React 18</th><th>功能说明</th></tr></thead><tbody><tr><td><code>ref()</code></td><td><code>useState()</code></td><td>Vue 的基本响应式单值；React 的基本状态钩子</td></tr><tr><td><code>reactive()</code></td><td><code>useState()</code> / <code>useReducer()</code></td><td>Vue 深层响应；React 需使用对象/Reducer 管理复杂状态</td></tr><tr><td><code>readonly()</code></td><td>无</td><td>React 默认不变，Vue 可显式标注只读</td></tr></tbody></table><hr><h2 id="✅-派生状态-计算值" tabindex="-1">✅ 派生状态（计算值） <a class="header-anchor" href="#✅-派生状态-计算值" aria-label="Permalink to “✅ 派生状态（计算值）”">​</a></h2><table tabindex="0"><thead><tr><th>Vue 3</th><th>React 18</th><th>功能说明</th></tr></thead><tbody><tr><td><code>computed(() =&gt; ...)</code></td><td><code>useMemo(() =&gt; ..., [deps])</code></td><td>Vue 自动依赖收集，React 手动管理依赖</td></tr></tbody></table><hr><h2 id="✅-副作用监听" tabindex="-1">✅ 副作用监听 <a class="header-anchor" href="#✅-副作用监听" aria-label="Permalink to “✅ 副作用监听”">​</a></h2><table tabindex="0"><thead><tr><th>Vue 3</th><th>React 18</th><th>功能说明</th></tr></thead><tbody><tr><td><code>watch(source, cb)</code></td><td><code>useEffect(() =&gt; ..., [deps])</code></td><td>Vue 可监听 ref/reactive，React 监听 state/props</td></tr><tr><td><code>watchEffect(cb)</code></td><td><code>useEffect(() =&gt; ..., [deps])</code></td><td>Vue 自动依赖追踪；React 需手动写 deps</td></tr><tr><td><code>onUnmounted(cb)</code></td><td><code>useEffect</code> 的返回值清理函数</td><td>都在组件卸载时执行</td></tr></tbody></table><hr><h2 id="✅-生命周期对照" tabindex="-1">✅ 生命周期对照 <a class="header-anchor" href="#✅-生命周期对照" aria-label="Permalink to “✅ 生命周期对照”">​</a></h2><table tabindex="0"><thead><tr><th>生命周期阶段</th><th>Vue 3</th><th>React 18</th></tr></thead><tbody><tr><td>挂载</td><td><code>onMounted()</code></td><td><code>useEffect(() =&gt; {}, [])</code></td></tr><tr><td>卸载</td><td><code>onUnmounted()</code></td><td><code>useEffect(() =&gt; { return () =&gt; {} }, [])</code></td></tr><tr><td>更新</td><td><code>onUpdated()</code></td><td>无等价，<code>useEffect(() =&gt; {}, [deps])</code> 可近似</td></tr><tr><td>错误捕获</td><td><code>onErrorCaptured()</code></td><td><code>&lt;ErrorBoundary&gt;</code>（类组件）</td></tr><tr><td>DOM 更新后</td><td><code>nextTick()</code></td><td><code>setTimeout(..., 0)</code> 或微任务</td></tr></tbody></table><hr><h2 id="✅-dom-引用" tabindex="-1">✅ DOM 引用 <a class="header-anchor" href="#✅-dom-引用" aria-label="Permalink to “✅ DOM 引用”">​</a></h2><table tabindex="0"><thead><tr><th>Vue 3</th><th>React 18</th><th>功能说明</th></tr></thead><tbody><tr><td><code>ref=&quot;el&quot;</code> + <code>elRef.value</code></td><td><code>useRef()</code> + <code>ref={elRef}</code></td><td>都可访问原生 DOM 元素</td></tr></tbody></table><hr><h2 id="✅-依赖注入与共享" tabindex="-1">✅ 依赖注入与共享 <a class="header-anchor" href="#✅-依赖注入与共享" aria-label="Permalink to “✅ 依赖注入与共享”">​</a></h2><table tabindex="0"><thead><tr><th>Vue 3</th><th>React 18</th><th>功能说明</th></tr></thead><tbody><tr><td><code>provide/inject</code></td><td><code>createContext/useContext</code></td><td>Vue 灵活支持跨层注入；React 组件树结构限制更大</td></tr><tr><td><code>pinia</code></td><td>Redux / Zustand 等</td><td>全局状态管理库，功能对等</td></tr></tbody></table><hr><h2 id="✅-suspense-异步组件" tabindex="-1">✅ Suspense/异步组件 <a class="header-anchor" href="#✅-suspense-异步组件" aria-label="Permalink to “✅ Suspense/异步组件”">​</a></h2><table tabindex="0"><thead><tr><th>Vue 3</th><th>React 18</th><th>功能说明</th></tr></thead><tbody><tr><td><code>defineAsyncComponent</code></td><td><code>React.lazy()</code></td><td>支持懒加载组件</td></tr><tr><td><code>&lt;Suspense&gt;</code></td><td><code>&lt;Suspense&gt;</code></td><td>同名组件，用法类似</td></tr></tbody></table><hr><h2 id="✅-逻辑复用" tabindex="-1">✅ 逻辑复用 <a class="header-anchor" href="#✅-逻辑复用" aria-label="Permalink to “✅ 逻辑复用”">​</a></h2><table tabindex="0"><thead><tr><th>Vue 3</th><th>React 18</th><th>功能说明</th></tr></thead><tbody><tr><td>Composable (<code>useXxx</code>)</td><td>自定义 Hook (<code>useXxx</code>)</td><td>封装逻辑复用方式完全一致</td></tr></tbody></table><hr><h2 id="✅-并发特性-react-专属" tabindex="-1">✅ 并发特性（React 专属） <a class="header-anchor" href="#✅-并发特性-react-专属" aria-label="Permalink to “✅ 并发特性（React 专属）”">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>Vue 3</th><th>React 18</th></tr></thead><tbody><tr><td>并发渲染</td><td>❌</td><td>✅ <code>startTransition()</code></td></tr><tr><td><code>useTransition</code></td><td>❌</td><td>✅</td></tr><tr><td><code>useDeferredValue</code></td><td>❌</td><td>✅</td></tr></tbody></table><hr><h2 id="🧭-项目迁移建议-vue-→-react" tabindex="-1">🧭 项目迁移建议（Vue → React） <a class="header-anchor" href="#🧭-项目迁移建议-vue-→-react" aria-label="Permalink to “🧭 项目迁移建议（Vue → React）”">​</a></h2><ul><li><code>ref</code> → <code>useState</code></li><li><code>reactive</code> → <code>useState({})</code> 或 <code>useReducer</code></li><li><code>computed</code> → <code>useMemo</code></li><li><code>watch/watchEffect</code> → <code>useEffect</code></li><li><code>onMounted/onUnmounted</code> → <code>useEffect(..., [])</code></li><li><code>ref=&quot;el&quot;</code> → <code>useRef()</code></li><li>插槽 <code>&lt;slot&gt;</code> → <code>props.children</code></li><li><code>provide/inject</code> → <code>Context.Provider</code> / <code>useContext</code></li></ul><hr><h2 id="🔗-参考" tabindex="-1">🔗 参考 <a class="header-anchor" href="#🔗-参考" aria-label="Permalink to “🔗 参考”">​</a></h2><ul><li>Vue 官网：<a href="https://vuejs.org" target="_blank" rel="noreferrer">https://vuejs.org</a></li><li>React 官网：<a href="https://react.dev" target="_blank" rel="noreferrer">https://react.dev</a></li></ul>',33))])}const x=a(n,[["render",s]]);export{R as __pageData,x as default};
